// genuary31
//
// some other pixelsort:
// why not we take fixed white noise, and swap pixels as to match a video...
// ...needs a power of 2 buffer size to work properly
// ...so on shadertoy pixels might get lost over time

uniform float Inverse; // ...or sort as bad as possible to not match video and show invertred image

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord.xy / iResolution.xy;
    fragColor = texture(iChannel0,uv);
    if(Inverse>.5) fragColor = 1.-fragColor;
    fragColor *= fragColor*1.6;
    fragColor.w=1.;
}

// created by florian berger (flockaroo) - 2025
// License Creative Commons Attribution-NonCommercial-ShareAlike 3.0 Unported License.
//
// genuary31
//
// some other pixelsort:
// why not we take fixed white noise, and swap pixels as to match a video...
// ...needs a power of 2 buffer size to work properly
// ...so on shadertoy pixels might get lost over time

#define VidTex iChannel1
#define RandTex iChannel2

uniform float Inverse; // ...or sort as bad as possible to not match video and show invertred image

int bitinvN(int x, int num) { int r=0,m=1<<(num-1); for(;m>0;x>>=1,m>>=1) r|=m*(x&1); return r; }

void mainImage( out vec4 fragColor, vec2 fragCoord )
{
    ivec2 ires=textureSize(iChannel3,0);
    ivec2 voff=ivec2(0);
    ivec2 vres=textureSize(VidTex,0);
    // fit video to aspect ration of screen
    { int x2=vres.y*int(iResolution.x)/int(iResolution.y); voff.x=(vres.x-x2)/2; vres.x=x2; }
    vec2 Res=vec2(ires);

    // vary size of sorting kernel in time
    ivec2 Bits=ivec2(5,5)+ivec2(sin(iTime-vec2(0,1.57))*2.);

    // varying offset of sorting kernel
    ivec2 off=ivec2(iFrame*7,iFrame*3)*1;

    // actual pixel coord
    ivec2 fci=ivec2(fragCoord);
    // 2nd pixels coord
    ivec2 siz=ivec2(1<<Bits.x,1<<Bits.y);
    ivec2 fcmod=(fci+off)%siz;
    ivec2 fci2=fci-fcmod;
    if (fci2.x<0) fci2.x+=ires.x;
    if (fci2.y<0) fci2.y+=ires.y;
    fci2+=ivec2(
        bitinvN(fcmod.x,Bits.x),
        bitinvN(fcmod.y,Bits.y)
        );
    fci2=fci2%ires;

    // exchange 2 pixels if better match for video
    vec4 c1=texelFetch(iChannel3,fci,0);
    vec4 c2=texelFetch(iChannel3,fci2,0);
    vec4 v1=texelFetch(VidTex,fci *vres/ires+voff,0);
    vec4 v2=texelFetch(VidTex,fci2*vres/ires+voff,0);
    float actWin=dot(abs(v1-c1).xyz,abs(v2-c2).xyz);
    float newWin=dot(abs(v1-c2).xyz,abs(v2-c1).xyz);
    if ( newWin <= actWin ^^ Inverse>.5 ) c1=c2;

    fragColor=c1;

    // init with white noise
    if(iFrame<60) fragColor = texelFetch(RandTex,fci%256,0)*.9+.1*texelFetch(RandTex,(fci*ivec2(3,7))%256,0);
}
